export interface ChunkRef {
  index: number;
  sha256: string;
  size: number;
}

export interface BlobStore {
  putChunk(fileId: string, chunk: ChunkRef, data: Buffer, signal: AbortSignal): Promise<void>;
  commitFile(fileId: string, chunks: ChunkRef[], signal: AbortSignal): Promise<{ version: number }>;
}

export class DeadlineExceededError extends Error {
  constructor(public readonly stage: string) {
    super(`sync deadline exceeded during ${stage}`);
  }
}

export async function withTimeout<T>(
  ms: number,
  stage: string,
  op: (signal: AbortSignal) => Promise<T>,
): Promise<T> {
  if (ms <= 0) throw new DeadlineExceededError(stage);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    return await op(controller.signal);
  } catch (err) {
    if (controller.signal.aborted) throw new DeadlineExceededError(stage);
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

import { createHash } from "crypto";
import { BlobStore, ChunkRef, withTimeout } from "./blobStore";

const CHUNK_SIZE = 4 * 1024 * 1024;
const PER_CHUNK_CAP_MS = 15_000;

export interface SyncResult {
  fileId: string;
  version: number;
  uploadedChunks: number;
  skippedChunks: number;
}

export class FileSyncUploader {
  constructor(
    private readonly store: BlobStore,
    private readonly knownChunks: (fileId: string) => Promise<Set<string>>,
  ) {}

  async sync(fileId: string, contents: Buffer, budgetMs: number): Promise<SyncResult> {
    const startedAt = Date.now();
    const deadlineAt = startedAt + budgetMs;
    const existing = await this.knownChunks(fileId);

    const chunks: ChunkRef[] = [];
    let uploaded = 0;
    let skipped = 0;

    for (let offset = 0, index = 0; offset < contents.length; offset += CHUNK_SIZE, index++) {
      const data = contents.subarray(offset, offset + CHUNK_SIZE);
      const ref: ChunkRef = {
        index,
        sha256: createHash("sha256").update(data).digest("hex"),
        size: data.length,
      };
      chunks.push(ref);

      if (existing.has(ref.sha256)) {
        skipped++;
        continue;
      }

      const remaining = deadlineAt - startedAt;
      await withTimeout(Math.min(remaining, PER_CHUNK_CAP_MS), `chunk ${index}`, (signal) =>
        this.store.putChunk(fileId, ref, data, signal),
      );
      uploaded++;
    }

    const { version } = await withTimeout(deadlineAt - Date.now(), "commit", (signal) =>
      this.store.commitFile(fileId, chunks, signal),
    );

    return { fileId, version, uploadedChunks: uploaded, skippedChunks: skipped };
  }
}

import { FileSyncUploader } from "./uploader";
import { DeadlineExceededError } from "./blobStore";

export interface SyncRequest {
  fileId: string;
  contents: Buffer;
  clientDeadlineMs?: number;
}

const DEFAULT_BUDGET_MS = 60_000;
const MAX_BUDGET_MS = 300_000;

export async function handleSync(uploader: FileSyncUploader, req: SyncRequest) {
  const budget = Math.min(req.clientDeadlineMs ?? DEFAULT_BUDGET_MS, MAX_BUDGET_MS);
  try {
    const result = await uploader.sync(req.fileId, req.contents, budget);
    return { status: 200, body: result };
  } catch (err) {
    if (err instanceof DeadlineExceededError) {
      return { status: 504, body: { error: "sync_deadline_exceeded", stage: err.stage } };
    }
    throw err;
  }
}
